import { assert, assertEmptyRest, assertUint8AnySize } from './assertUint8.mjs'
import { fromUint8Super } from './output.mjs'

// Transforms the internal coder into a user-facing API
export function createCipherApi(usage, { encrypt, decrypt }) {
  if (usage !== undefined) assert(usage === 'encrypt' || usage === 'decrypt')
  const result = Object.create(null)
  if (usage === undefined || usage === 'encrypt') {
    result.encrypt = async ({ data, nonce, format, additionalData, ...rest }) => {
      assertEmptyRest(rest)
      assertUint8AnySize(data, 'data')
      assertUint8AnySize(nonce, 'nonce')
      if (additionalData !== undefined) assertUint8AnySize(additionalData, 'additionalData')
      return fromUint8Super(await encrypt(data, nonce, additionalData), format)
    }
  }
  if (usage === undefined || usage === 'decrypt') {
    result.decrypt = async ({ data, nonce, format, additionalData, ...rest }) => {
      assertEmptyRest(rest)
      assertUint8AnySize(data, 'data')
      assertUint8AnySize(nonce, 'nonce')
      if (additionalData !== undefined) assertUint8AnySize(additionalData, 'additionalData')
      return fromUint8Super(await decrypt(data, nonce, additionalData), format)
    }
  }
  return result
}

// Binds parameters to cipher constructor, creating single-call encrypt/decrypt
export const directMethods = (cipher, ...args) => ({
  async encrypt({ key, nonce, data, format, additionalData, ...rest }) {
    assertEmptyRest(rest)
    const { encrypt } = await cipher(...args, key, 'encrypt')
    return encrypt({ data, nonce, format, additionalData })
  },

  async decrypt({ key, nonce, data, format, additionalData, ...rest }) {
    assertEmptyRest(rest)
    const { decrypt } = await cipher(...args, key, 'decrypt')
    return decrypt({ data, nonce, format, additionalData })
  },
})
